from typing import Iterable, List
from hourglass.parsing import format_clock
from hourglass.models import Span
from hourglass.merging import merge_spans

class OutsideHoursError(ValueError):
    """A worked span falls outside opening hours."""

def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[Span]:
    """Stretches of opening hours that no span covers."""
    merged = merge_spans(worked)
    for span in merged:
        if span.start < opening.start:
            raise OutsideHoursError(span)
        if span.end > opening.end:
            raise OutsideHoursError(span)

    gaps = []
    cursor = opening.start
    for span in merged:
        if span.start > cursor:
            gaps.append(Span(cursor, span.start))
        cursor = span.end
    if cursor < opening.end:
        gaps.append(Span(cursor, opening.end))
    return gaps

def gap_labels(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    """One label per gap, like gap 12:00-13:00 (60 min)."""
    labels = []
    for stretch in find_gaps(worked, opening):
        start = format_clock(stretch.start)
        stop = format_clock(stretch.end)
        size = stretch.minutes
        labels.append(f"gap {start}-{stop} ({size} min)")
    return labels

